var i=`0318-ratatouille`;var n=`world-0318`;var a=`FR`;var l=`western-europe`;var r=4;var o=52;var s={en:`Ratatouille`,ua:`Рататуй`};var g={en:`A traditional France dish made with eggplant, zucchini, red bell pepper, yellow onion. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Франція. Основні інгредієнти: баклажан, цукіні, червоний солодкий перець, жовта цибуля. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var u=[{en:`Cut the vegetables evenly and roast at 200°C for about 18 minutes until tender and lightly charred.`,ua:`Наріжте овочі рівномірно та запікайте при 200°C приблизно 18 хвилин до м’якості й легкої підпеченої скоринки.`,t:[`roasting`],m:18,i:[[`eggplant`,400,`g`],[`zucchini`,400,`g`],[`red-bell-pepper`,270,`g`],[`extra-virgin-olive-oil`,65,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 9 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 9 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:9,i:[[`yellow-onion`,150,`g`],[`tomato`,450,`g`],[`garlic`,4,`clove`],[`thyme`,3,`sprig`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 25 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 25 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:25,i:[[`basil`,20,`g`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]}];var d={slug:i,id:n,country:`FR`,region:l,servings:4,minutes:52,title:s,text:g,steps:u};export{a as country,d as default,n as id,o as minutes,l as region,r as servings,i as slug,u as steps,g as text,s as title};